import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, inviteAndJoin } from './helpers';

// Fresh 2-node game: pageA is white (node 0, host), pageB is black (node 1).
async function startNewGame(pageA: import('@playwright/test').Page, pageB: import('@playwright/test').Page) {
  await inviteAndJoin(pageA, pageB);
  await expect(pageA.getByTestId('action-create_game')).toBeVisible({ timeout: 15_000 });
  await pageA.getByTestId('action-create_game').click();
  await expect(pageA.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
  await expect(pageB.getByTestId('chess-board')).toBeVisible({ timeout: 5_000 });
}

test.describe(`player: submit my move when I'm ready`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a player submits a legal move, the opponent's board reflects the new position within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await startNewGame(pageA, pageB);

    await pageA.getByTestId('square-e2').click();
    await pageA.getByTestId('square-e4').click();
    await pageA.getByTestId('action-submit_move').click();

    await expect(pageB.getByTestId('square-e4')).toContainText('♙', { timeout: 5_000 });
    await expect(pageB.getByTestId('square-e2')).not.toContainText('♙');

    await ctxA.close();
    await ctxB.close();
  });

  test(`an illegal move is rejected and the shared state is unchanged`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await startNewGame(pageA, pageB);

    // A pawn cannot jump from e2 straight to e5 (3 squares) — illegal.
    await pageA.getByTestId('square-e2').click();
    await pageA.getByTestId('square-e5').click();
    await pageA.getByTestId('action-submit_move').click();

    // Rejected: an error is surfaced and the shared board is unchanged for
    // both players.
    await expect(pageA.locator('text=/error|fail|reject|illegal|invalid/i').first()).toBeVisible({
      timeout: 5_000,
    });
    await expect(pageA.getByTestId('square-e2')).toContainText('♙');
    await expect(pageA.getByTestId('square-e5')).not.toContainText('♙');
    await expect(pageB.getByTestId('square-e2')).toContainText('♙');
    await expect(pageB.getByTestId('square-e5')).not.toContainText('♙');

    await ctxA.close();
    await ctxB.close();
  });

  test(`a player cannot submit a move when it is not their turn`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await startNewGame(pageA, pageB);

    // It is White's (pageA's) turn — Black (pageB) cannot even preview a
    // move, since the board only accepts clicks on the current player's turn.
    await pageB.getByTestId('square-e7').click();
    await pageB.getByTestId('square-e5').click();
    await expect(pageB.getByTestId('action-submit_move')).toBeDisabled();
    await expect(pageB.getByTestId('square-e5')).not.toContainText('♟');

    await ctxA.close();
    await ctxB.close();
  });
});
